import { StrictMode, useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { io } from 'socket.io-client';
import './styles.css';

type Question = { id?: string; label: string; choices: string[]; answerIndex?: number };
type Quiz = { id: string; title: string; status: 'DRAFT' | 'OPEN' | 'CLOSED'; durationSeconds: number; questions: Question[]; openedAt?: string };
type Session = { id: string; name: string };
type Ranking = { total: number; ranking: { rank:number; name:string; score:number; submittedAt:string }[] };
const API = import.meta.env.VITE_API_URL ?? 'http://localhost:3000';
const request = async <T,>(path: string, init?: RequestInit): Promise<T> => {
  // A JSON content type without a body makes Fastify reject requests such as admin login.
  const extraHeaders = init?.headers as Record<string, string> | undefined;
  const headers = { ...(init?.body ? { 'Content-Type': 'application/json' } : {}), ...extraHeaders };
  const response = await fetch(`${API}${path}`, { ...init, headers });
  if (!response.ok) throw new Error((await response.json().catch(()=>({}))).message ?? 'Une erreur est survenue');
  return response.json();
};
const adminHeaders = (password:string) => ({ 'x-admin-password': password });

function App() {
  const [quizzes, setQuizzes] = useState<Quiz[]>([]); const [view, setView] = useState<'auth'|'menu'|'quiz'|'admin'>('auth');
  const [session, setSession] = useState<Session | null>(() => JSON.parse(localStorage.getItem('etsia-session') ?? 'null'));
  const [selected, setSelected] = useState<Quiz | null>(null); const [password,setPassword] = useState('');
  const load = () => request<Quiz[]>('/api/quizzes').then(setQuizzes).catch(()=>undefined);
  useEffect(() => { load(); const socket = io(API); socket.on('quizzes:changed', setQuizzes); return () => { socket.disconnect(); }; }, []);
  useEffect(() => { if (session) setView('menu'); }, [session]);
  const login = async (name:string, accessCode:string, register:boolean) => { const next = await request<Session>(`/api/session/${register?'register':'login'}`, { method:'POST', body:JSON.stringify({name,accessCode}) }); localStorage.setItem('etsia-session', JSON.stringify(next)); setSession(next); };
  if (view === 'auth') return <Auth onParticipant={login} onAdmin={async p=>{ await request('/api/admin/login',{method:'POST',headers:adminHeaders(p)});setPassword(p);setView('admin'); }} />;
  if (view === 'admin') return <Admin password={password} onExit={()=>setView(session?'menu':'auth')} />;
  if (view === 'quiz' && selected && session) return <QuizRun quiz={selected} session={session} onDone={()=>{setSelected(null);setView('menu');}}/>;
  return <ParticipantMenu quizzes={quizzes} session={session!} onOpen={quiz=>{setSelected(quiz);setView('quiz');}} onLogout={()=>{localStorage.removeItem('etsia-session');setSession(null);setView('auth');}}/>;
}

function Auth({onParticipant,onAdmin}:{onParticipant:(name:string,code:string,register:boolean)=>Promise<void>;onAdmin:(password:string)=>Promise<void>}) {
  const [mode,setMode] = useState<'login'|'register'|'admin'>('login'); const [name,setName]=useState(''); const [code,setCode]=useState(''); const [error,setError]=useState('');
  const submit=async(e:React.FormEvent)=>{e.preventDefault();try{mode==='admin'?await onAdmin(code):await onParticipant(name,code,mode==='register');}catch(err){setError(err instanceof Error?err.message:'Erreur de connexion');}};
  const change=(next:typeof mode)=>{setMode(next);setError('');setCode('');};
  return <main className="landing"><section className="brand-panel"><div className="orb orb-one"/><div className="orb orb-two"/><p className="kicker">ETSIA · 2027</p><h1>Le quiz qui fait vibrer les idées.</h1><p>Explorez les projets, répondez au bon moment et montez au classement.</p><div className="pills"><span>Mobile first</span><span>9 projets</span><span>90 secondes</span></div></section><section className="auth-panel"><div className="logo-mark">E</div><h2>{mode==='admin'?'Espace administration':mode==='register'?'Créer mon accès':'Content de vous revoir'}</h2><p>{mode==='admin'?'Accès réservé à l équipe d organisation.':mode==='register'?'Utilisez un nom et un code dont vous vous souviendrez.':'Connectez-vous pour retrouver votre tableau de bord.'}</p><form onSubmit={submit}>{mode!=='admin'&&<label>Nom complet<input value={name} required minLength={2} placeholder="Ex. Wilfried D." onChange={e=>setName(e.target.value)}/></label>}<label>{mode==='admin'?'Mot de passe administrateur':'Code de sécurité'}<input type="password" value={code} required minLength={4} placeholder="••••••••" onChange={e=>setCode(e.target.value)}/></label>{error&&<p className="error">{error}</p>}<button className="primary wide">{mode==='admin'?'Ouvrir le cockpit':mode==='register'?'Créer mon compte':'Me connecter'} <span>→</span></button></form>{mode==='login'&&<button className="text-button" onClick={()=>change('register')}>Première visite ? Créer un compte</button>}{mode==='register'&&<button className="text-button" onClick={()=>change('login')}>J ai déjà un compte</button>}<button className="admin-link" onClick={()=>change(mode==='admin'?'login':'admin')}>{mode==='admin'?'← Retour participant':'Accès administrateur'}</button></section></main>;
}

function ParticipantMenu({quizzes,session,onOpen,onLogout}:{quizzes:Quiz[];session:Session;onOpen:(q:Quiz)=>void;onLogout:()=>void}) { const open=quizzes.find(q=>q.status==='OPEN'); return <main className="app-shell"><header className="topbar"><div><p className="kicker">ETSIA 2027</p><h1>Bonjour, {session.name.split(' ')[0]} 👋</h1></div><button className="avatar" onClick={onLogout} title="Se déconnecter">{session.name[0]?.toUpperCase()}</button></header><section className="hero-card"><div><span className="live-dot">● En direct</span><h2>{open ? `${open.title} est ouvert` : 'La prochaine idée arrive bientôt'}</h2><p>{open?'Le compte à rebours démarre au moment où vous entrez.':'Restez sur cette page : les quiz s ouvrent en temps réel.'}</p></div><div className="hero-number">{String(quizzes.length).padStart(2,'0')}<small>projets</small></div></section><section><div className="section-title"><div><p className="kicker">PARCOURS</p><h2>Les projets</h2></div><span>{quizzes.filter(q=>q.status==='OPEN').length} disponible</span></div><div className="quiz-grid">{quizzes.map((q,i)=><button key={q.id} className={`project-card ${q.status.toLowerCase()}`} disabled={q.status!=='OPEN'} onClick={()=>onOpen(q)}><span className="project-index">{String(i+1).padStart(2,'0')}</span><span className="project-status">{q.status==='OPEN'?'Jouer maintenant':'🔒'}</span><strong>{q.title}</strong><small>{q.status==='CLOSED'?'Quiz terminé':q.status==='OPEN'?`${q.questions.length} questions · ${q.durationSeconds}s`:'En attente d ouverture'}</small></button>)}</div></section><button className="logout-button" onClick={onLogout}>Se déconnecter</button></main> }

function QuizRun({quiz,session,onDone}:{quiz:Quiz;session:Session;onDone:()=>void}) { const [answers,setAnswers]=useState<number[]>(Array(quiz.questions.length).fill(-1));const [score,setScore]=useState<number|null>(null);const [error,setError]=useState('');const [startedAt,setStartedAt]=useState<string>(); const deadline=useMemo(()=>startedAt?new Date(startedAt).getTime()+quiz.durationSeconds*1000:0,[startedAt,quiz]); const [seconds,setSeconds]=useState(quiz.durationSeconds); useEffect(()=>{request<{startedAt:string}>(`/api/quizzes/${quiz.id}/start`,{method:'POST',body:JSON.stringify({participantId:session.id})}).then(r=>setStartedAt(r.startedAt)).catch(e=>setError(e instanceof Error?e.message:'Impossible de démarrer le quiz'));},[quiz.id,session.id]); useEffect(()=>{if(!deadline)return;const timer=setInterval(()=>setSeconds(Math.max(0,Math.ceil((deadline-Date.now())/1000))),250);return()=>clearInterval(timer)},[deadline]); const submit=async()=>{try{const result=await request<{score:number}>(`/api/quizzes/${quiz.id}/submit`,{method:'POST',body:JSON.stringify({participantId:session.id,answers})});setScore(result.score)}catch(e){setError(e instanceof Error?e.message:'Impossible d enregistrer les réponses');}};if(score!==null)return <main className="result-page"><div className="result-icon">✓</div><p className="kicker">RÉPONSES ENREGISTRÉES</p><h1>Bien joué, {session.name.split(' ')[0]} !</h1><p>Votre score est de <b>{score}/{quiz.questions.length}</b>. Les résultats seront publiés par les organisateurs.</p><button className="primary" onClick={onDone}>Retour aux projets</button></main>;return <main className="quiz-page"><header className="quiz-head"><button className="back" onClick={onDone}>← Quitter</button><div><p className="kicker">QUIZ EN COURS</p><h1>{quiz.title}</h1></div><div className={`timer ${seconds<=15?'urgent':''}`}>{String(Math.floor(seconds/60)).padStart(2,'0')}:{String(seconds%60).padStart(2,'0')}</div></header>{!startedAt&&!error?<p>Préparation de votre temps personnel…</p>:null}<div className="progress"><i style={{width:`${answers.filter(a=>a>=0).length/quiz.questions.length*100}%`}}/></div><section className="question-list">{quiz.questions.map((q,qi)=><article className="question-card" key={q.id}><span className="question-number">0{qi+1}</span><h2>{q.label}</h2><div className="options">{q.choices.map((choice,ci)=><button key={choice} className={answers[qi]===ci?'selected':''} onClick={()=>setAnswers(old=>old.map((a,i)=>i===qi?ci:a))}><span>{String.fromCharCode(65+ci)}</span>{choice}</button>)}</div></article>)}{error&&<p className="error">{error}</p>}<button className="primary submit" disabled={answers.includes(-1)||seconds===0||!startedAt} onClick={submit}>Envoyer mes réponses <span>→</span></button></section></main> }

const blankQuestion=():Question=>({label:'',choices:['','','',''],answerIndex:0});
function Admin({password,onExit}:{password:string;onExit:()=>void}){const [quizzes,setQuizzes]=useState<Quiz[]>([]);const [editing,setEditing]=useState<Quiz|null>(null);const [ranking,setRanking]=useState<Ranking|null>(null);const [notice,setNotice]=useState(''); const headers=adminHeaders(password); const load=()=>request<Quiz[]>('/api/admin/quizzes',{headers}).then(setQuizzes).catch(e=>setNotice(e.message));useEffect(()=>{load()},[]);const save=async()=>{if(!editing)return;try{if(editing.id.startsWith('new-'))await request('/api/admin/quizzes',{method:'POST',headers,body:JSON.stringify({...editing,id:undefined})});else await request(`/api/admin/quizzes/${editing.id}`,{method:'PATCH',headers,body:JSON.stringify(editing)});setEditing(null);load()}catch(e){setNotice(e instanceof Error?e.message:'Erreur de sauvegarde')}}; const action=async(path:string,method='POST')=>{try{await request(path,{method,headers});load()}catch(e){setNotice(e instanceof Error?e.message:'Erreur')}}; const create=()=>setEditing({id:`new-${Date.now()}`,title:'Nouveau projet',status:'DRAFT',durationSeconds:90,questions:[blankQuestion(),blankQuestion(),blankQuestion()]}); return <main className="admin-shell"><aside><div className="admin-brand"><span>ETSIA</span><b>Control room</b></div><button className="nav-active">▦ Vue d ensemble</button><button onClick={create}>＋ Nouveau quiz</button><button onClick={onExit}>← Quitter l admin</button><small>Configuration locale<br/>Prête pour PostgreSQL</small></aside><section className="admin-content"><header><div><p className="kicker">PILOTAGE ÉVÉNEMENT</p><h1>Tableau de bord</h1></div><button className="primary" onClick={create}>Créer un quiz</button></header>{notice&&<p className="error">{notice}</p>}{editing?<QuizEditor quiz={editing} setQuiz={setEditing} onSave={save} onCancel={()=>setEditing(null)}/>:ranking?<RankingView ranking={ranking} onBack={()=>setRanking(null)}/>:<section className="admin-list">{quizzes.map(q=><article key={q.id} className="admin-quiz"><div className={`status-chip ${q.status.toLowerCase()}`}>{q.status==='OPEN'?'● OUVERT':q.status==='CLOSED'?'TERMINÉ':'BROUILLON'}</div><div className="admin-quiz-main"><h2>{q.title}</h2><p>{q.questions.length} questions · {q.durationSeconds} secondes</p></div><div className="admin-actions">{q.status==='DRAFT'&&<button className="primary" onClick={()=>confirm(`Ouvrir ${q.title} ?`)&&action(`/api/admin/quizzes/${q.id}/open`)}>Ouvrir</button>}{q.status==='OPEN'&&<button className="danger" onClick={()=>confirm(`Finaliser ${q.title} ?`)&&action(`/api/admin/quizzes/${q.id}/close`)}>Finaliser</button>}<button onClick={()=>setEditing(q)} disabled={q.status==='OPEN'}>Modifier</button><button onClick={async()=>{try{setRanking(await request<Ranking>(`/api/admin/quizzes/${q.id}/ranking`,{headers}))}catch(e){setNotice(e instanceof Error?e.message:'Erreur')}}}>Résultats</button><button onClick={()=>confirm('Réinitialiser les participations ?')&&action(`/api/admin/quizzes/${q.id}/reset`)} disabled={q.status==='OPEN'}>Réinitialiser</button><button className="delete" onClick={()=>confirm(`Supprimer ${q.title} ?`)&&action(`/api/admin/quizzes/${q.id}`,'DELETE')} disabled={q.status==='OPEN'}>Supprimer</button></div></article>)}</section>}</section></main>}

function QuizEditor({quiz,setQuiz,onSave,onCancel}:{quiz:Quiz;setQuiz:(q:Quiz)=>void;onSave:()=>void;onCancel:()=>void}){const updateQuestion=(index:number,change:Partial<Question>)=>setQuiz({...quiz,questions:quiz.questions.map((q,i)=>i===index?{...q,...change}:q)});return <section className="editor"><header><button className="back" onClick={onCancel}>← Annuler</button><div><p className="kicker">ÉDITEUR DE QUIZ</p><h1>{quiz.id.startsWith('new-')?'Nouveau quiz':'Modifier le quiz'}</h1></div></header><label>Titre du projet<input value={quiz.title} onChange={e=>setQuiz({...quiz,title:e.target.value})}/></label><label>Durée (secondes)<input type="number" min="30" max="600" value={quiz.durationSeconds} onChange={e=>setQuiz({...quiz,durationSeconds:Number(e.target.value)})}/></label><div className="editor-questions">{quiz.questions.map((q,qi)=><article className="edit-question" key={qi}><div className="question-editor-head"><b>Question {qi+1}</b><button className="delete" onClick={()=>setQuiz({...quiz,questions:quiz.questions.filter((_,i)=>i!==qi)})} disabled={quiz.questions.length===1}>Retirer</button></div><input placeholder="Écrivez votre question" value={q.label} onChange={e=>updateQuestion(qi,{label:e.target.value})}/>{q.choices.map((choice,ci)=><label className="answer-row" key={ci}><input type="radio" name={`correct-${qi}`} checked={q.answerIndex===ci} onChange={()=>updateQuestion(qi,{answerIndex:ci})}/><input placeholder={`Réponse ${String.fromCharCode(65+ci)}`} value={choice} onChange={e=>updateQuestion(qi,{choices:q.choices.map((v,i)=>i===ci?e.target.value:v)})}/></label>)}</article>)}</div><button onClick={()=>setQuiz({...quiz,questions:[...quiz.questions,blankQuestion()]})}>+ Ajouter une question</button><div className="editor-footer"><button onClick={onCancel}>Annuler</button><button className="primary" onClick={onSave}>Enregistrer le quiz</button></div></section>}
function RankingView({ranking,onBack}:{ranking:Ranking;onBack:()=>void}){return <section className="ranking"><button className="back" onClick={onBack}>← Retour</button><p className="kicker">CLASSEMENT</p><h1>Top 10</h1><p>{ranking.total} participant{ranking.total>1?'s':''}</p>{ranking.ranking.length?<ol>{ranking.ranking.map(item=><li key={item.rank}><b>#{item.rank}</b><span>{item.name}</span><strong>{item.score} pts</strong><small>{new Date(item.submittedAt).toLocaleTimeString()}</small></li>)}</ol>:<p>Aucune participation pour le moment.</p>}</section>}
createRoot(document.getElementById('root')!).render(<StrictMode><App/></StrictMode>);
